#include <iostream>
using namespace std;

const int MAXN = 1005;
const int MAXM = 20005;
int head[MAXN], to[MAXM], nxt[MAXM], weight[MAXM], ecnt = 0;

void addEdge(int u, int v, int w) {
    to[ecnt] = v; weight[ecnt] = w; nxt[ecnt] = head[u]; head[u] = ecnt++;
    to[ecnt] = u; weight[ecnt] = w; nxt[ecnt] = head[v]; head[v] = ecnt++;
}

int main() {
    memset(head, -1, sizeof(head));
    addEdge(1, 2, 5);
    addEdge(2, 3, 3);
    return 0;
}

