#include <queue>
using namespace std;

void bfs(int start) {
    queue<int> q;
    q.push(start);
    vis[start] = true;  // 入队即标记
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj[u]) {
            if (!vis[v]) {
                vis[v] = true;  // 入队即标记
                q.push(v);
            }
        }
    }
}

