void addEdgeUnique(int u, int v, int w) {
    // 保留最短的重边
    for (int i = head[u]; i != -1; i = nxt[i]) {
        if (to[i] == v) {
            weight[i] = min(weight[i], w);
            return;
        }
    }
    addEdge(u, v, w);
}

practice.expectedIdea:
void addEdgeMin(int u, int v, int w) {
    for (int i = head[u]; ~i; i = nxt[i]) {
        if (to[i] == v) { weight[i] = min(weight[i], w); return; }
    }
    addEdge(u, v, w);
}

